// The widget's slim data slice (data/widget-hexagrams.json, ~25 KB) — bundled
// into the widget extension so it stays well inside the tight widget memory
// budget. Generated by scripts/build_widget_slice.py from hexagrams*.json.

import Foundation
import OracleKit

struct SlimHex: Codable {
    let number: Int
    let binary: String
    let name_de: String?
    let name_en: String?
    let lead_de_neutral: String?
    let lead_de_historical: String?
    let lead_en_neutral: String?
    let lead_en_historical: String?

    func name(_ s: OracleSettings) -> String {
        (s.lang == .en ? name_en : name_de) ?? name_de ?? name_en ?? "#\(number)"
    }

    func lead(_ s: OracleSettings) -> String {
        switch (s.lang, s.register) {
        case (.de, .neutral):    return lead_de_neutral ?? lead_de_historical ?? ""
        case (.de, .historical): return lead_de_historical ?? ""
        case (.en, .neutral):    return lead_en_neutral ?? lead_en_historical ?? ""
        case (.en, .historical): return lead_en_historical ?? ""
        }
    }
}

enum SlimData {
    static let all: [SlimHex] = {
        guard let url = Bundle.main.url(forResource: "widget-hexagrams", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let arr = try? JSONDecoder().decode([SlimHex].self, from: data) else { return [] }
        return arr
    }()

    static func forNumber(_ n: Int) -> SlimHex? { all.first { $0.number == n } }
}
